const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const portLocation = ee.Geometry.Point([-62.240, -38.790]); // Ingeniero White port coordinates
  const roi = portLocation.buffer(10000); // 10 km radius

  const date1_start = '2025-01-28'; // A few days around the target date
  const date1_end = '2025-02-01'; // January 30, 2025

  const date2_start = '2025-03-09'; // A few days around the target date
  const date2_end = '2025-03-13'; // March 11, 2025

  const S1_POLARIZATION = 'VV';
  const S1_ORBIT = 'DESCENDING'; // Use a consistent orbit for comparison
  const S1_SCALE = 10; // Sentinel-1 native resolution

  // Function to process Sentinel-1 images for inundation detection
  function detectInundation(image) {
    // Apply radiometric calibration, terrain correction to gamma0.
    // Use 'GRD_FLOOD' processing graph for typical flood mapping.
    image = ee.Image(image).select(S1_POLARIZATION).unitScale(0, 1).log10().multiply(10); // Convert to dB scale

    // Apply a threshold to detect water. Water generally has very low backscatter.
    // A common threshold for open water is around -18 to -20 dB for VV.
    // Values less than the threshold are considered water.
    const waterMask = image.lt(-18);

    // Apply a simple speckle filter.
    const filtered = image.focal_median(30, 'circle', 'meters').updateMask(waterMask);

    // Use the water mask directly for area calculation.
    return filtered.gt(-18).rename('water');
  }

  // Function to get and process Sentinel-1 collection for a given date range
  function getInundationArea(startDate, endDate, roi, dateLabel) {
    let collection = ee.ImageCollection('COPERNICUS/S1_GRD')
      .filterBounds(roi)
      .filterDate(startDate, endDate)
      .filter(ee.Filter.listContains('transmitterReceiverPolarisation', S1_POLARIZATION))
      .filter(ee.Filter.eq('instrumentMode', 'IW'))
      .filter(ee.Filter.eq('orbitProperties_pass', S1_ORBIT));

    const size = collection.size().getInfo();
    if (size === 0) {
      console.log(`No Sentinel-1 images found for ${dateLabel} (${startDate} to ${endDate}).`);
      return { area: null, count: 0, imageSize: 0 };
    }

    // Get the median image to reduce speckle and cloud effects (though S1 is all-weather).
    // Ensure we process only the relevant bands.
    let image = collection.median().select(S1_POLARIZATION);

    if (image.bandNames().getInfo().length === 0) {
      console.log(`No valid bands found in median image for ${dateLabel}.`);
      return { area: null, count: 0, imageSize: size };
    }

    const inundationImage = detectInundation(image);

    // Calculate valid pixels
    const pixelCount = inundationImage.gt(0).reduceRegion({
      reducer: ee.Reducer.count(),
      geometry: roi,
      scale: S1_SCALE,
      maxPixels: 1e9
    }).get('water').getInfo();

    if (pixelCount === 0 || pixelCount === null) {
      console.log(`No valid water pixels after processing for ${dateLabel}. Images: ${size}`);
      return { area: null, count: 0, imageSize: size };
    }

    // Calculate area of inundation in square kilometers
    const inundationArea = inundationImage.multiply(ee.Image.pixelArea()).reduceRegion({
      reducer: ee.Reducer.sum(),
      geometry: roi,
      scale: S1_SCALE,
      maxPixels: 1e9
    }).get('water').getInfo();

    return {
      area: inundationArea / 1e6, // Convert m^2 to km^2
      count: pixelCount,
      imageSize: size
    };
  }

  // 2. Data Acquisition & Check and 3. Processing
  console.log("--- Analyzing Jan 30, 2025 ---");
  const result1 = getInundationArea(date1_start, date1_end, roi, 'Jan 30, 2025');

  console.log("--- Analyzing Mar 11, 2025 ---");
  const result2 = getInundationArea(date2_start, date2_end, roi, 'Mar 11, 2025');

  // 4. Validation and Final Answer
  if (result1.area === null) {
    if (result1.imageSize === 0) {
      console.log("C1: No images found for Jan 30, 2025.");
    } else {
      console.log("C2: No valid pixels after processing for Jan 30, 2025.");
    }
    console.log("C1"); // If first date fails, we can't compare
    return;
  }
  if (result2.area === null) {
    if (result2.imageSize === 0) {
      console.log("C1: No images found for Mar 11, 2025.");
    } else {
      console.log("C2: No valid pixels after processing for Mar 11, 2025.");
    }
    console.log("C1"); // If second date fails, we can't compare
    return;
  }

  // Ensure results are numeric and valid for comparison
  if (isNaN(result1.area) || isNaN(result2.area)) {
    console.log("C3: Calculation resulted in NaN for inundation area.");
    console.log("C3");
    return;
  }

  console.log(`Jan 30, 2025: Inundation Area = ${result1.area.toFixed(2)} km², Images Used: ${result1.imageSize}, Valid Water Pixels: ${result1.count}`);
  console.log(`Mar 11, 2025: Inundation Area = ${result2.area.toFixed(2)} km², Images Used: ${result2.imageSize}, Valid Water Pixels: ${result2.count}`);

  if (result2.area > result1.area) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
